import fs from 'node:fs';

export const EXPORT_START = '<!-- agentroom:context -->';
export const EXPORT_END = '<!-- /agentroom:context -->';

/**
 * The repo map as a marked block for CLAUDE.md / AGENTS.md, so plain Claude Code (and other agents)
 * get it too. Only text between the markers is ever replaced; everything else stays as written.
 */
export function upsertContextBlock(existing: string, index: string): string {
  const block = [
    EXPORT_START,
    '<!-- Generated by `agentroom context export` from .agentroom/context/INDEX.md. Edits inside this block are overwritten. -->',
    index.trim(),
    'Module cards: `.agentroom/context/modules/<id>.md` (read the one you need; human notes there are authoritative).',
    EXPORT_END,
  ].join('\n');
  const start = existing.indexOf(EXPORT_START);
  const end = existing.indexOf(EXPORT_END, start + 1);
  if (start >= 0 && end > start) return existing.slice(0, start) + block + existing.slice(end + EXPORT_END.length);
  if (!existing.trim()) return block + '\n';
  return existing.replace(/\s*$/, '') + '\n\n' + block + '\n';
}

/** Writes the block into `file` (created when missing). Returns true when the file changed. */
export function exportContextBlock(file: string, index: string): boolean {
  const before = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : '';
  const after = upsertContextBlock(before, index);
  if (after === before) return false;
  fs.writeFileSync(file, after);
  return true;
}
